/**
 * Risolve la definizione SVG con risoluzione gerarchica di fallback
 */
export function getIconDefinition(
  name: string,
  family: IconFamily = 'classic',
  weight: IconWeight = 'regular'
): IconDefinition {
  const cleanName = name.replace(/^fa-/, '').toLowerCase();

  // 1. Chiave esatta
  const exactKey = `${family}:${weight}:${cleanName}`;
  if (iconRegistry[exactKey]) return iconRegistry[exactKey];

  // 2. Se brands, prova brands:regular:name
  if (family === 'brands') {
    const brandKey = `brands:regular:${cleanName}`;
    if (iconRegistry[brandKey]) return iconRegistry[brandKey];
  }

  // 3. Prova peso alternativo nella stessa famiglia (solid <-> regular)
  const altWeight = weight === 'solid' ? 'regular' : 'solid';
  const altWeightKey = `${family}:${altWeight}:${cleanName}`;
  if (iconRegistry[altWeightKey]) return iconRegistry[altWeightKey];

  // 4. Prova classic:solid:name o classic:regular:name
  if (family !== 'classic') {
    const classicSolidKey = `classic:solid:${cleanName}`;
    if (iconRegistry[classicSolidKey]) return iconRegistry[classicSolidKey];
    const classicRegularKey = `classic:regular:${cleanName}`;
    if (iconRegistry[classicRegularKey]) return iconRegistry[classicRegularKey];
  }

  // 5. Cerca qualsiasi variante registrata per questo nome
  const suffix = `:${cleanName}`;
  for (const [key, def] of Object.entries(iconRegistry)) {
    if (key.endsWith(suffix)) return def;
  }

  // 6. Fallback finale
  return FALLBACK_ICON;
}
